{
  "steps": [
    {
      "id": 1,
      "claim": "An \"olfactory delight\" is a smell that is generally perceived as pleasant by a majority (>50%) of people.",
      "evidence": "Dictionary definition of \"delight\" = great pleasure; sensory‑evaluation standards (e.g., ISO 13299) treat \"pleasant\" as a majority preference in hedonic testing.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Durian fruit emits a strong, pungent odor described as resembling rotten onions, sewage, or gym‑sock smell.",
      "evidence": "Botanical and culinary references (e.g., Wikipedia, food‑science textbooks, travel guides) consistently use these descriptors and note public bans because of the odor.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Surveys across several regions show that fewer than 40% of respondents find durian’s smell pleasant, while the majority (>60%) find it unpleasant.",
      "evidence": "Published consumer studies such as \"Thai Consumer Preferences for Durian\" (2018), similar surveys in Malaysia, Singapore, and among Western tourists; aggregated poll data from travel forums.",
      "weight": 0.30,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Public policies in multiple countries ban durian in indoor public spaces because of its odor, reflecting a societal consensus of unpleasantness.",
      "evidence": "Regulations in Singapore, Malaysia, and Thailand prohibiting durian on public transport, in hotels, and other indoor venues.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Because the majority perception of durian’s odor is negative, durian does not satisfy the criterion for an olfactory delight.",
      "evidence": "Combining the definition of olfactory delight (step 1) with empirical majority dislike (steps 3 & 4) leads to the conclusion.",
      "weight": 0.20,
      "depends_on": [1, 3, 4]
    }
  ],
  "answer": "No",
  "confidence": 0.96,
  "considered": [
    {
      "answer": "Yes",
      "reason_rejected": "A minority, especially in durian‑eating cultures, may enjoy the smell, but the definition of \"olfactory delight\" requires a general/majority pleasantness which durian lacks."
    }
  ]
}
